mapper.select:
SELECT 
FROM sys_user u
WHERE u.deleted = 0

    AND (u.username LIKE CONCAT('%', #{q.keyword}, '%')
         OR u.real_name LIKE CONCAT('%', #{q.keyword}, '%'))


    AND u.status = #{q.status}


    AND EXISTS (
        SELECT 1 FROM sys_user_role ur WHERE ur.user_id = u.id AND ur.role_id = #{q.roleId}
    )

ORDER BY u.created_time DESC

mapper.update:
UPDATE sys_user
real_name = #{realName}, phone = #{phone}, email = #{email}, department = #{department}, password = #{password}, daily_limit = #{dailyLimit}, status = #{status}, error_count = #{errorCount}, locked_until = #{lockedUntil}, updated_time = NOW()
WHERE id = #{id}
